-- Swiss 2027 dates imported as 'confirmed' (44 markets, 780 dates), each
-- checked against the organiser's or commune's own page on 2026-10-08
-- (scratchpad agents; results kept in intake/descriptions/checked-2027-dates.json).
--   published — the organiser lists the date, or a current standing rule covers
--     it: stamped today with the source in the facts ledger (what confirm.mjs does);
--   not published — the organiser has only 2026 up, or the rhythm bends: stays on
--     the page as 'unverified' ("Not confirmed yet"), stamp cleared;
--   excluded by the organiser's own rule — removed (Kanzlei 1 May and 25 Dec,
--     CPO in the Vaud winter holidays, Plainpalais on 1 August).
-- Plainpalais closes at 17:15 in winter (geneve.ch/marche-plainpalais, 2026-05-07);
-- winter taken as Swiss winter time.

begin;

create temporary table d_pub (slug text, date date, url text) on commit drop;
create temporary table d_unv (slug text, date date) on commit drop;
create temporary table d_del (slug text, date date) on commit drop;

do $$
declare n int;
begin
  -- An empty database (the CI schema test) has nothing to correct.
  if not exists (select 1 from public.markets) then return; end if;
  update public.occurrences o set confirmed_at = now(), updated_at = now()
    from d_pub p join public.markets m on m.slug = p.slug
   where o.market_id = m.id and o.date = p.date and o.status = 'confirmed';
  get diagnostics n = row_count;
  if n <> 702 then raise exception 'published: expected 702, got %', n; end if;

  select 'occurrence', o.id, 'date', to_jsonb(o.date::text), 'website_crawl', p.url, now(), 'confirmed'
    from d_pub p join public.markets m on m.slug = p.slug join public.occurrences o on o.market_id = m.id and o.date = p.date;

  update public.occurrences o set status = 'unverified', confirmed_at = null, updated_at = now()
    from d_unv u join public.markets m on m.slug = u.slug
   where o.market_id = m.id and o.date = u.date and o.status = 'confirmed';
  get diagnostics n = row_count;
  if n <> 74 then raise exception 'unverified: expected 74, got %', n; end if;

  delete from public.occurrences o using d_del x, public.markets m
   where m.slug = x.slug and o.market_id = m.id and o.date = x.date;
  get diagnostics n = row_count;
  if n <> 4 then raise exception 'removed: expected 4, got %', n; end if;
end $$;

update public.occurrences o set end_time = '17:15', updated_at = now()
  from public.markets m
 where m.slug like 'marche-aux-puces-plainpalais-geneve-%' and o.market_id = m.id and o.end_time = '18:15'
   and ((o.date between '2026-10-25' and '2027-03-27') or o.date >= '2027-10-31');

commit;
